<!--
 * 消息发送表单组件
 *
 * @path apps/message-web/src/views/message/message-form.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为契约 API：发送表单（MessageSendDTO）提交 send()。
-->
<script lang="ts" setup>
/**
 * 消息（发送表单组件）
 * <p>消费后端契约 MessageController#send（src/api/message.ts，auto-generated by bash/gen-contract.py）：
 * 按 MessageSendDTO 字段（strategy/channel/receiver/bizType/subject/content/templateCode 等）填写发送表单，
 * 提交成功后 emit('success') 并关闭弹窗。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { useYDSZModal } from '@ydsz/common-ui';
import {
  ElForm,
  ElFormItem,
  ElInput,
  ElMessage,
  ElOption,
  ElRadio,
  ElRadioGroup,
  ElSelect,
} from 'element-plus';
import { reactive, ref } from 'vue';

import { send } from '#/api/message';

const emit = defineEmits<{ success: [] }>();

const formRef = ref();

/** 发送表单状态（字段对应 MessageSendDTO） */
interface MessageFormState {
  strategy: 'SYNC' | 'DIRECT' | 'ASYNC' | 'TRANSACTIONAL' | 'BATCH';
  channel: string;
  receiver: string;
  bizType: string;
  subject: string;
  content: string;
  templateCode: string;
  bizId: string;
  priority: string;
  senderId: string;
  messageGroup: string;
}

const formData = reactive<MessageFormState>({
  strategy: 'SYNC',
  channel: '',
  receiver: '',
  bizType: '',
  subject: '',
  content: '',
  templateCode: '',
  bizId: '',
  priority: '',
  senderId: '',
  messageGroup: '',
});

const rules = {
  channel: [{ required: true, message: '请输入发送通道', trigger: 'blur' }],
  receiver: [{ required: true, message: '请输入接收者', trigger: 'blur' }],
};

const [Modal, modalApi] = useYDSZModal({
  onOpenChange: (isOpen: boolean) => {
    if (!isOpen) return;
    Object.assign(formData, {
      strategy: 'SYNC',
      channel: '',
      receiver: '',
      bizType: '',
      subject: '',
      content: '',
      templateCode: '',
      bizId: '',
      priority: '',
      senderId: '',
      messageGroup: '',
    });
  },
  onConfirm: async () => {
    try {
      await formRef.value?.validate();
    } catch {
      return;
    }
    modalApi.lock();
    try {
      await send({
        strategy: formData.strategy,
        channel: formData.channel,
        receiver: formData.receiver,
        bizType: formData.bizType,
        subject: formData.subject,
        content: formData.content,
        templateCode: formData.templateCode || undefined,
        bizId: formData.bizId || undefined,
        priority: formData.priority || undefined,
        senderId: formData.senderId || undefined,
        messageGroup: formData.messageGroup || undefined,
      });
      ElMessage.success('发送成功');
      emit('success');
      modalApi.close();
    } finally {
      modalApi.unlock();
    }
  },
});
</script>
<template>
  <Modal title="发送消息">
    <ElForm
      ref="formRef"
      :model="formData"
      :rules="rules"
      label-width="100px"
      label-position="right"
    >
      <ElFormItem label="发送策略" prop="strategy">
        <ElRadioGroup v-model="formData.strategy">
          <ElRadio value="SYNC">同步</ElRadio>
          <ElRadio value="DIRECT">直发</ElRadio>
          <ElRadio value="ASYNC">异步</ElRadio>
          <ElRadio value="TRANSACTIONAL">事务</ElRadio>
        </ElRadioGroup>
      </ElFormItem>
      <ElFormItem label="通道" prop="channel">
        <ElInput v-model="formData.channel" placeholder="请输入通道，如 SMS/EMAIL/IN_APP" />
      </ElFormItem>
      <ElFormItem label="接收者" prop="receiver">
        <ElInput v-model="formData.receiver" placeholder="请输入接收者" />
      </ElFormItem>
      <ElFormItem label="业务类型" prop="bizType">
        <ElInput v-model="formData.bizType" placeholder="请输入业务类型" />
      </ElFormItem>
      <ElFormItem label="业务ID" prop="bizId">
        <ElInput v-model="formData.bizId" placeholder="请输入业务ID" />
      </ElFormItem>
      <ElFormItem label="模板编码" prop="templateCode">
        <ElInput v-model="formData.templateCode" placeholder="请输入模板编码（可为空）" />
      </ElFormItem>
      <ElFormItem label="主题" prop="subject">
        <ElInput v-model="formData.subject" placeholder="请输入主题（可为空）" />
      </ElFormItem>
      <ElFormItem label="内容" prop="content">
        <ElInput v-model="formData.content" type="textarea" :rows="3" placeholder="请输入内容" />
      </ElFormItem>
      <ElFormItem label="优先级" prop="priority">
        <ElSelect v-model="formData.priority" placeholder="请选择优先级（可为空）" clearable>
          <ElOption label="高" value="HIGH" />
          <ElOption label="中" value="MEDIUM" />
          <ElOption label="低" value="LOW" />
        </ElSelect>
      </ElFormItem>
      <ElFormItem label="消息组" prop="messageGroup">
        <ElInput v-model="formData.messageGroup" placeholder="请输入消息组（可为空）" />
      </ElFormItem>
    </ElForm>
  </Modal>
</template>
